        if (index, prev) not in memo:
            take = 0
            if prev == -1 or any(is_divisible(a[prev], a[i]) for i in range(index)):
                take = 1 + dfs(index + 1, index, memo)
            not_take = dfs(index + 1, prev, memo)
            memo[index, prev] = max(take, not_take)
        return memo[index, prev]

    a.sort()
    return dfs(0, -1, defaultdict(int))
